'use strict';
const E=AthletEngine,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const equipment=['Trainingsmatte','Kurzhanteln','Widerstandsband','Balancekissen'];
const days=['Mo','Di','Mi','Do','Fr','Sa','So'];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=(date,opts={day:'numeric',month:'short'})=>new Date(date+'T12:00:00').toLocaleDateString('de-DE',opts);
const defaultProfile={sports:['Reiten'],equipment:['Trainingsmatte'],count:3,minutes:30,goals:[],competitions:[]};
let currentStorageKey='athlet-v1';
let state={profile:structuredClone(defaultProfile),plans:{},completed:[],sunday:null},storageWorks=true;
try{const raw=JSON.parse(localStorage.getItem('athlet-v1'));if(raw&&raw.profile&&Array.isArray(raw.profile.sports)&&Array.isArray(raw.profile.equipment)){state={...state,...raw,profile:{...defaultProfile,...raw.profile}};}}catch{}
let selectedWeek=E.weekKey(),page='overview',interval=null,active=null,installPrompt=null;
function save(){try{localStorage.setItem(currentStorageKey,JSON.stringify(state));}catch{storageWorks=false;toast('Speichern nicht möglich. Bitte prüfe den Speicher deines Browsers.');}$('.saved-indicator').innerHTML='<i></i> '+(storageWorks?'Lokal gespeichert':'Nur für diese Sitzung');}
if(!state.plans[selectedWeek]){state.plans[selectedWeek]=E.generate(state.profile,selectedWeek);save();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const plan=()=>state.plans[selectedWeek]||[];
const weekRange=w=>{const d=E.monday(new Date(w+'T12:00:00'));const end=new Date(d);end.setDate(end.getDate()+6);return `${d.getDate()}. – ${end.toLocaleDateString('de-DE',{day:'numeric',month:'long'})}`;};
const done=s=>state.completed.includes(s.id);
function weekShift(n){const d=E.monday(new Date(selectedWeek+'T12:00:00'));d.setDate(d.getDate()+n*7);selectedWeek=E.iso(d);render();}
function illustration(){return `<svg class="hero-art" viewBox="0 0 420 280" fill="none" aria-hidden="true"><circle cx="252" cy="146" r="117" fill="#e0e8cf"/><circle cx="252" cy="146" r="90" stroke="#ccd9b7" stroke-dasharray="3 7"/><path d="M9 251c99-38 243-30 400-9" stroke="#cedab9"/><path d="M293 239c11-20 8-53-4-68M293 218c14-16 31-19 43-18M293 228c-19-9-31-7-42-4" stroke="#a7b887" stroke-width="2"/><path d="M290 170c-13 2-17 18-5 23 9-1 13-11 5-23M336 199c-12-8-30 1-26 10 11 5 23-1 26-10M250 224c7-11 24-8 27 2-5 9-18 8-27-2" fill="#b6c69d"/><path d="m235 156-44 49-63 3" stroke="#2c4939" stroke-width="22" stroke-linecap="round" stroke-linejoin="round"/><path d="m232 159 29 34-18 47" stroke="#36573f" stroke-width="23" stroke-linecap="round" stroke-linejoin="round"/><path d="m129 208-20 3-6 9 27-1" fill="#bdc7a1"/><path d="m244 238-5 11 29 3c3-6-7-10-13-12" fill="#b1c197"/><path d="m210 117-29 23-28-15" stroke="#bd9573" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/><path d="m240 115 23 14 18-28" stroke="#bd9573" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/><path d="M223 96c-15 2-20 9-22 23l10 50c11 9 28 9 36-5l1-50c-3-12-12-19-25-18" fill="#f9faf0"/><path d="m220 105 13-5-2-21-13 2z" fill="#bd9573"/><ellipse cx="225" cy="70" rx="17" ry="20" transform="rotate(10 225 70)" fill="#c8a282"/><path d="M209 72c-7-15 2-33 18-31 9 0 20 8 18 20-8 3-16-3-20-9 0 14-9 15-16 20" fill="#2a4233"/><path d="M211 43c-8-17-26-11-22 1 3 9 14 10 22-1" fill="#2a4233"/><path d="m152 125-4-11M280 101l5-8" stroke="#bd9573" stroke-width="9" stroke-linecap="round"/><path d="M105 81h24m-12-12v24" stroke="#b2c296" stroke-width="2"/><circle cx="333" cy="86" r="5" fill="#c2d19f"/><path d="m129 177 5-9m-6 4 9 3" stroke="#a8bd8b" stroke-width="2"/><rect x="283" y="145" width="89" height="31" rx="10" fill="#f8faef" transform="rotate(-8 283 145)"/><text x="296" y="163" fill="#71865b" font-size="10" font-family="sans-serif" transform="rotate(-8 283 145)">✳ In Balance.</text></svg>`;}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><span class="eyebrow">DEIN TRAINING. DEIN RHYTHMUS.</span><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
const editButton=()=>'<button class="button primary" data-action="edit">Woche planen <span>＋</span></button>';
function sessionCard(s,i){return `<article class="session-card"><div class="session-icon ${i%3===1?'orange':i%3===2?'purple':''}">${['↗','◎','✳'][i%3]}</div><div class="session-main"><div class="session-top"><h3>${escape(s.focus)}</h3><span class="tag ${s.light?'orange':''}">${done(s)?'✓ Erledigt':s.light?'Vor Wettkampf':i===0?'Dein nächster Schritt':'Ergänzendes Training'}</span></div><p class="session-meta">${dateLabel(s.date,{weekday:'long',day:'numeric',month:'short'})}<span>·</span>${s.minutes} Min.<span>·</span>${s.blocks.length} Übungen</p></div><button class="session-arrow" data-detail="${s.id}" aria-label="${escape(s.focus)} ansehen">↗</button></article>`;}
function overview(){const p=state.profile,items=plan(),completed=items.filter(done).length,total=items.reduce((a,s)=>a+s.minutes,0);const today=E.iso(new Date());const next=items.find(s=>!done(s)&&s.date>=today)||items.find(s=>!done(s));const sunday=new Date().getDay()===0&&state.sunday!==E.weekKey();return `${heading('Deine Woche. Dein Fortschritt.','Training, das zu deinem Sport und deinem Leben passt.',editButton())}${sunday?'<div class="sunday-banner"><div><b>Sonntag ist Planungstag. ☀</b>Wie viel Zeit hast du nächste Woche für dich?</div><button class="button" data-action="next-week">Nächste Woche planen ↗</button></div>':''}<section class="hero"><div class="hero-copy"><span class="pill">✳ DEIN ERGÄNZENDER TRAININGSPLAN</span><h2>Stärker für deinen Sport.<br><em>In deinem Rhythmus.</em></h2><p>Mehr Balance, mehr Beweglichkeit, mehr du.<br>Dein Plan verbindet, was dich weiterbringt.</p><button class="button primary" ${next?`data-start="${next.id}"`:'data-action="edit"'}>${next?'Nächstes Training starten':'Neue Woche planen'} <span>↗</span></button></div>${illustration()}</section><div class="stats"><div class="stat"><span class="stat-label">Einheiten diese Woche</span><span class="stat-icon">▦</span><div class="stat-value">${items.length}<small>Einheiten</small></div><span class="stat-bottom">Gut verteilt. Gut für dich.</span></div><div class="stat"><span class="stat-label">Deine Trainingszeit</span><span class="stat-icon">◷</span><div class="stat-value">${total}<small>Minuten</small></div><span class="stat-bottom">${p.minutes} Minuten pro Einheit</span></div><div class="stat"><span class="stat-label">Deine Sportarten</span><span class="stat-icon">↗</span><div class="stat-value">${p.sports.length}<small>${p.sports.length===1?'Sportart':'Sportarten'}</small></div><span class="stat-bottom">Individuell auf dich abgestimmt</span></div><div class="stat"><span class="stat-label">Schon geschafft</span><span class="stat-icon">✓</span><div class="stat-value">${completed}<small>von ${items.length}</small></div><span class="stat-bottom">${completed?'Jede Einheit zählt. Weiter so!':'Dein erster Schritt wartet auf dich.'}</span></div></div><div class="two-col"><section><div class="section-head"><h2>Dein Wochenplan</h2><a href="#plan">${weekRange(selectedWeek)} <span>↗</span></a></div><div class="week-strip">${days.map((day,i)=>{const d=E.monday(new Date(selectedWeek+'T12:00:00'));d.setDate(d.getDate()+i);return `<div class="day ${items.some(s=>s.day===i)?'scheduled':''} ${E.iso(d)===today?'today':''}">${day}<b>${d.getDate()}</b><span class="dot"></span></div>`;}).join('')}</div>${items.map(sessionCard).join('')||'<div class="empty">Für diese Woche gibt es noch keinen Plan.</div>'}<p class="data-note">✳ Zwischen deinen Einheiten: Raum für deinen Sport und deine Erholung.</p></section><aside class="right-column"><div class="panel"><div class="section-head"><h3>Auf dich abgestimmt</h3><a href="#profile" aria-label="Sportprofil bearbeiten">↗</a></div><p class="sub">Die Grundlage für deinen Ausgleich.</p><div class="sport-chips">${p.sports.map(s=>`<span class="sport-chip">${escape(s)}</span>`).join('')}</div><div class="panel-divider"></div><div class="equipment-info">${escape(p.equipment.join(' · ')||'Training mit dem eigenen Körpergewicht')}<br>${escape([...new Set(p.sports.flatMap(s=>(E.sports[s]?.muscles||'').split(' · ')))].join(' · '))}</div></div><div class="panel"><div class="section-head"><h3>Deine Ziele im Blick</h3><a href="#goals" aria-label="Ziele bearbeiten">↗</a></div><p class="sub">Wofür bewegst du dich?</p>${p.goals.filter(g=>!g.done).slice(0,2).map(g=>`<div class="goal-mini"><span class="goal-symbol">⚑</span><div><b>${escape(g.title)}</b><small>${escape(g.focus)}${g.date?' · '+dateLabel(g.date):''}</small></div></div>`).join('')||'<div class="goal-mini"><span class="goal-symbol">⚑</span><div><b>Dein nächstes Ziel</b><small><a href="#goals">Ein Ziel hinzufügen ↗</a></small></div></div>'}</div><div class="quote-card"><span class="flower">✳</span><h3>Ausgleich macht den Unterschied.</h3><p>Dein ergänzendes Training schafft Platz für Kraft, Beweglichkeit und ein gutes Körpergefühl.</p><div class="tiny">EIN SCHRITT NACH DEM ANDEREN.</div></div></aside></div>`;}
function planPage(){return `${heading('Dein Wochenplan.','Ein guter Plan lässt auch Platz zum Durchatmen.',editButton())}<div class="section-head plan-heading"><h2>Training & Erholung</h2><div class="week-control"><button class="icon-button" data-shift="-1" aria-label="Vorherige Woche">‹</button><b>${weekRange(selectedWeek)}</b><button class="icon-button" data-shift="1" aria-label="Nächste Woche">›</button><button class="button soft" data-action="current-week">Heute</button></div></div><div class="calendar-grid">${days.map((day,i)=>{const d=E.monday(new Date(selectedWeek+'T12:00:00'));d.setDate(d.getDate()+i);const s=plan().find(s=>s.day===i);const races=state.profile.competitions.filter(c=>c.date===E.iso(d));return `<div class="calendar-col"><div class="cal-day">${day}<strong>${d.getDate()}</strong></div><div>${s?`<button class="cal-session" data-detail="${s.id}"><b>${done(s)?'✓ ':''}${escape(s.focus)}</b><small>${s.minutes} Min. · ${s.blocks.length} Übungen<br>${s.light?'Lockere Intensität':'Ergänzendes Training'}</small></button>`:'<p class="rest">Zeit für deinen Sport<br>oder Erholung</p>'}${races.map(c=>`<div class="cal-session" style="background:#faf0e4"><b>⚑ ${escape(c.name)}</b><small>Wettkampf · ${escape(c.sport)}</small></div>`).join('')}</div></div>`;}).join('')}</div>${!plan().length?'<div class="empty" style="margin-top:20px">Für diese Woche fehlt noch dein Plan.<br><button class="button primary" data-action="edit">Jetzt planen ↗</button></div>':''}<div class="info-box"><b>Was in deinem Plan steckt</b><p>Aufwärmen, sportbezogene Kräftigung, ${state.profile.sports.some(s=>E.sports[s]?.coord)?'Koordination, ':''}Ausdauer, Mobilität und sanftes Dehnen. Ziele steuern den Schwerpunkt. Wettkämpfe sorgen kurz vor dem Termin für lockere Aktivierung.</p></div><p class="data-note">Die Wochenplanung ergänzt deinen Hauptsport. Dessen Belastung wird in dieser ersten Version noch nicht automatisch erfasst. Passe Umfang und Intensität an dein Tagesgefühl an.</p>`;}
function goalsPage(){return `${heading('Ein Ziel vor Augen.','Was du erreichen möchtest, gibt deinem Training eine Richtung.')}<div class="two-col"><section><div class="section-head"><h2>Deine Ziele</h2><small>${state.profile.goals.filter(g=>!g.done).length} aktiv</small></div>${state.profile.goals.map(g=>`<div class="goal-card ${g.done?'done':''}"><span class="goal-symbol">⚑</span><div class="goal-text"><h3>${escape(g.title)}</h3><p>${escape(g.focus)}${g.date?' · bis '+dateLabel(g.date,{day:'numeric',month:'long',year:'numeric'}):''}</p></div><button class="button soft" data-goal-toggle="${g.id}">${g.done?'Reaktivieren':'✓ Erreicht'}</button><button class="delete-btn" data-goal-delete="${g.id}" aria-label="Ziel löschen">×</button></div>`).join('')||'<div class="empty">Dein nächster Schritt beginnt mit einem Ziel.<br>Füge hier hinzu, was dir wichtig ist.</div>'}<div class="info-box">✳ Aktive Ziele verändern die Schwerpunkte neu erstellter Pläne. Erstelle deinen Wochenplan nach einer Änderung erneut.</div></section><aside><div class="panel"><h3>Ein neues Ziel setzen</h3><form id="goal-form"><label>Was möchtest du erreichen?<input name="title" required maxlength="80" placeholder="z. B. stabiler im Sattel sitzen"></label><label>Trainingsschwerpunkt<select name="focus"><option>Kraft</option><option>Ausdauer</option><option>Beweglichkeit</option><option>Koordination</option></select></label><label>Zieldatum (optional)<input type="date" name="date"></label><button type="submit" class="button primary full">Ziel hinzufügen ＋</button></form></div></aside></div>`;}
function profilePage(){return `${heading('So individuell wie du.','Deine Sportarten, deine Ausstattung und deine nächsten Wettkämpfe.')}<div class="two-col"><section><div class="panel"><div class="section-head"><h3>Dein Konto</h3><button data-account>Konto öffnen ↗</button></div><p class="sub" id="profile-account-name">Du nutzt Athlet als Gast.</p><button class="button soft" data-account>Google- oder Apple-Konto ↗</button><p class="data-note">Trainingsdaten bleiben auf diesem Gerät. Für jedes Konto werden sie getrennt gespeichert.</p></div><div class="panel"><h3>Dein Sport & deine Ausstattung</h3><p class="sub">Die Auswahl wird für neue Wochenpläne verwendet.</p><form id="profile-form"><fieldset><legend>Deine Sportarten</legend><div class="choices">${choices(Object.keys(E.sports),state.profile.sports,'sports')}</div></fieldset><fieldset><legend>Verfügbare Geräte</legend><div class="choices">${choices(equipment,state.profile.equipment,'equipment')}</div></fieldset><p class="muted">Keine Geräte? Die Übungen funktionieren auch mit deinem Körpergewicht.</p><button class="button primary" style="margin-top:20px" type="submit">Profil speichern ↗</button><p class="error" id="profile-error" role="alert"></p></form></div><div class="panel"><div class="section-head"><h3>Deine Wettkämpfe</h3><span class="tag">IM PLAN BERÜCKSICHTIGT</span></div>${state.profile.competitions.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(c=>`<div class="race-row"><div><strong>⚑ ${escape(c.name)}</strong><p>${dateLabel(c.date,{day:'numeric',month:'long',year:'numeric'})} · ${escape(c.sport)}</p></div><button class="delete-btn" data-race-delete="${c.id}" aria-label="Wettkampf löschen">×</button></div>`).join('')||'<p class="sub">Noch kein Wettkampf eingetragen. Dein nächster Start findet hier seinen Platz.</p>'}<p class="data-note">Nach Änderungen bitte die betroffenen Wochen neu planen. Zwei Tage vor und am Wettkampftag wird eine lockere Einheit eingeplant.</p></div><div class="panel"><h3>Deine App, deine Daten</h3><p class="sub">Deine Angaben bleiben lokal in diesem Browser. Mit einer Sicherung kannst du sie auf ein anderes Gerät übertragen.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="button" data-action="export">Daten sichern ↓</button><button class="button" data-action="import">Sicherung laden ↑</button><button class="button" data-action="install">App installieren ↗</button></div><input id="import-file" type="file" accept="application/json,.json" hidden><p class="data-note">Eine Web-App für Browser, iPhone, Android und iPad. Keine Veröffentlichung in den App-Stores.</p></div></section><aside><div class="panel"><h3>Wettkampf hinzufügen</h3><form id="race-form"><label>Bezeichnung<input name="name" required maxlength="80" placeholder="z. B. Frühjahrsturnier"></label><label>Datum<input name="date" type="date" required></label><label>Sportart<select name="sport">${state.profile.sports.map(s=>`<option>${escape(s)}</option>`).join('')}</select></label><button class="button primary full" type="submit">Wettkampf hinzufügen ＋</button></form></div><div class="quote-card"><span class="flower">☀</span><h3>Sonntag. Zeit für deinen Plan.</h3><p>Beim Öffnen am Sonntag fragt Athlet nach deiner nächsten Woche. Für eine Erinnerung bei geschlossener App nutze deinen Kalender.</p><button class="text-button" data-action="reminder">Kalendererinnerung speichern ↗</button></div></aside></div>`;}
function choices(values,selected,name){return values.map(v=>`<label class="choice"><input type="checkbox" name="${name}" value="${escape(v)}" ${selected.includes(v)?'checked':''}>${escape(v)}</label>`).join('');}
function render(){page=location.hash.slice(1)||'overview';if(!['overview','plan','goals','profile'].includes(page))page='overview';$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#page-label').textContent={overview:'Übersicht',plan:'Wochenplan',goals:'Meine Ziele',profile:'Sport & Ausstattung'}[page];$('#content').innerHTML=({overview,plan:planPage,goals:goalsPage,profile:profilePage}[page])();bindForms();window.dispatchEvent(new Event('athlet-profile-rendered'));}
function openEditor(next=false){const d=E.monday();if(next)d.setDate(d.getDate()+7);const target=next?E.iso(d):selectedWeek;const weeks=new Set([target,E.weekKey()]);for(let i=1;i<5;i++){const w=E.monday();w.setDate(w.getDate()+i*7);weeks.add(E.iso(w));}$('#week-select').innerHTML=[...weeks].sort().map(w=>`<option value="${w}" ${w===target?'selected':''}>${weekRange(w)}</option>`).join('');const f=$('#plan-form');f.elements.count.value=state.profile.count;f.elements.minutes.value=state.profile.minutes;$('#sport-choices').innerHTML=choices(Object.keys(E.sports),state.profile.sports,'sports');$('#equipment-choices').innerHTML=choices(equipment,state.profile.equipment,'equipment');$('#form-error').textContent='';$('#editor').showModal();}
function findSession(id){return Object.values(state.plans).flat().find(s=>s.id===id);}
function openDetail(id){const s=findSession(id);if(!s)return;$('#detail-content').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">${dateLabel(s.date,{weekday:'long',day:'numeric',month:'long'})}</span><h2>${escape(s.focus)}</h2></div><button class="icon-button close-dialog" aria-label="Schließen">×</button></div><p class="muted">${s.minutes} Minuten · ${s.blocks.length} Übungen · ${s.sports.map(escape).join(' + ')}</p>${s.light?`<div class="form-note">Lockere Aktivierung vor „${escape(s.race)}“. Bleibe im angenehmen, leichten Bereich.</div>`:''}${s.blocks.map((b,i)=>`<div class="exercise-row"><span class="exercise-number">${String(i+1).padStart(2,'0')}</span><div class="exercise-text"><b>${escape(b.name)}</b><p>${escape(b.instruction)}</p><span class="tag">${escape(b.kind)}</span></div><small>${clock(b.seconds)}</small></div>`).join('')}<p class="data-note">Bei Kraftübungen: 8 ruhige Wiederholungen, kurz pausieren und im Zeitfenster wiederholen. Seiten gleichmäßig wechseln. Bei Schmerzen oder Schwindel abbrechen.</p><div class="detail-actions"><button class="button primary" data-start="${s.id}">Training starten ▷</button><button class="button soft" data-complete="${s.id}">${done(s)?'Als offen markieren':'Als erledigt markieren ✓'}</button></div>`;$('#detail').showModal();}
const clock=sec=>`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;
function speak(text){if(!active?.voice||!('speechSynthesis'in window))return;try{speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='de-DE';utterance.rate=.92;speechSynthesis.speak(utterance);}catch{}}
function announce(){const b=active.session.blocks[active.index];speak(`${b.name}. ${b.instruction} ${b.reps?'Acht ruhige Wiederholungen, dann kurz pausieren. Wiederhole im Zeitfenster.':''} Du hast ${Math.round(b.seconds/60)} Minuten.`);}
function startWorkout(id){const s=findSession(id);if(!s)return;if($('#detail').open)$('#detail').close();stopTimer();active={session:s,index:0,remaining:s.blocks[0].seconds,running:false,voice:false,rep:0};drawWorkout();$('#workout').showModal();}
function drawWorkout(){if(!active)return;const a=active,b=a.session.blocks[a.index];$('#workout-content').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">DEIN TRAININGSMODUS</span><p style="font-size:12px;margin-top:6px">${escape(a.session.focus)}</p></div><button class="icon-button" data-action="exit-workout" aria-label="Training verlassen">×</button></div><div class="workout-progress">${a.session.blocks.map((_,i)=>`<span class="${i<a.index?'done':i===a.index?'current':''}"></span>`).join('')}</div><span class="workout-label">ÜBUNG ${a.index+1} VON ${a.session.blocks.length} · ${escape(b.kind).toUpperCase()}</span><h2 class="workout-title">${escape(b.name)}</h2><div class="timer" id="timer" role="timer">${clock(a.remaining)}</div><p class="workout-instruction">${escape(b.instruction)}</p>${b.reps?`<div class="workout-reps">8 ruhige Wiederholungen je Runde · kurz pausieren<br>Manuell mitzählen: <button class="button soft" data-action="rep" id="rep-btn">${a.rep} / 8 ＋</button><br><small>Bei 8 beginnt eine neue Runde. Beide Seiten gleichmäßig trainieren.</small></div>`:'<p class="muted">Ruhig atmen. Dein Tempo zählt.</p>'}<div class="workout-controls"><button class="button" data-action="previous" ${a.index===0?'disabled':''}>‹ Zurück</button><button class="button primary" data-action="play" id="play-btn">${a.running?'Ⅱ Pause':'▷ Starten'}</button><button class="button" data-action="next">${a.index===a.session.blocks.length-1?'Abschließen ✓':'Weiter ›'}</button></div><label class="voice-toggle"><input type="checkbox" id="voice" ${a.voice?'checked':''} ${!('speechSynthesis'in window)?'disabled':''}> Übungsansagen ${!('speechSynthesis'in window)?'(hier nicht verfügbar)':''}</label><p class="data-note">Timer läuft nur bei aktivem Training. Beim Verlassen der App wird pausiert.</p>`;}
function stopTimer(){if(interval)clearInterval(interval);interval=null;}
function togglePlay(){if(!active)return;if(active.running){pauseWorkout();return;}active.running=true;active.deadline=Date.now()+active.remaining*1000;announce();drawWorkout();interval=setInterval(()=>{if(!active?.running)return;const before=active.remaining;active.remaining=Math.max(0,Math.ceil((active.deadline-Date.now())/1000));const timer=$('#timer');if(timer)timer.textContent=clock(active.remaining);if(active.remaining===0){speak('Zeit geschafft. Weiter zur nächsten Übung.');advance(1);}else if(before!==active.remaining&&active.remaining<=3)speak(String(active.remaining));},200);}
function pauseWorkout(){stopTimer();if(active)active.running=false;if('speechSynthesis'in window)speechSynthesis.cancel();if(active)drawWorkout();}
function advance(delta){if(!active)return;const running=active.running;pauseWorkout();const next=active.index+delta;if(next>=active.session.blocks.length){finishWorkout();return;}active.index=Math.max(0,next);active.remaining=active.session.blocks[active.index].seconds;active.rep=0;drawWorkout();if(running)togglePlay();}
function finishWorkout(){const s=active.session;if(!done(s))state.completed.push(s.id);save();stopTimer();speak('Geschafft. Dein Training ist abgeschlossen.');active=null;$('#workout-content').innerHTML=`<div style="padding:35px 0"><span class="small-mark" style="font-size:64px">✳</span><h2 style="margin:20px 0 10px">Ein guter Schritt für dich.</h2><p class="muted">Du hast dein Training abgeschlossen.<br>Dein Fortschritt ist gespeichert.</p><button class="button primary close-dialog" style="margin-top:25px">Zurück zur Übersicht ↗</button></div>`;render();}
function toggleComplete(id){const s=findSession(id);if(!s)return;state.completed=done(s)?state.completed.filter(x=>x!==id):[...state.completed,id];save();if($('#detail').open)$('#detail').close();render();toast(done(s)?'Training als erledigt gespeichert.':'Training wieder offen.');}
function download(name,type,content){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reminder(){const d=new Date();d.setHours(18,0,0,0);d.setDate(d.getDate()+((7-d.getDay())%7));if(d<new Date())d.setDate(d.getDate()+7);const compact=E.iso(d).replaceAll('-','');const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');download('athlet-sonntag.ics','text/calendar;charset=utf-8',`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Athlet//Wochenplanung//DE\r\nBEGIN:VEVENT\r\nUID:athlet-weekly-planning@athlet.local\r\nDTSTAMP:${stamp}\r\nDTSTART:${compact}T180000\r\nDURATION:PT10M\r\nRRULE:FREQ=WEEKLY;BYDAY=SU\r\nSUMMARY:Athlet – Plane deine Trainingswoche\r\nDESCRIPTION:Öffne Athlet und lege Zeit und Einheiten für die nächste Woche fest.\r\nBEGIN:VALARM\r\nTRIGGER:PT0M\r\nACTION:DISPLAY\r\nDESCRIPTION:Zeit für deinen Wochenplan\r\nEND:VALARM\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`);toast('Kalenderdatei heruntergeladen. Öffne sie in deinem Kalender.');}
function bindForms(){const gf=$('#goal-form');if(gf)gf.onsubmit=ev=>{ev.preventDefault();const f=new FormData(gf);const title=f.get('title').trim();if(!title)return;state.profile.goals.push({id:crypto.randomUUID(),title,focus:f.get('focus'),date:f.get('date'),done:false});save();render();toast('Ziel gespeichert. Neue Pläne berücksichtigen es.');};const pf=$('#profile-form');if(pf)pf.onsubmit=ev=>{ev.preventDefault();const f=new FormData(pf),sports=f.getAll('sports');if(!sports.length){$('#profile-error').textContent='Wähle mindestens eine Sportart.';return;}state.profile.sports=sports;state.profile.equipment=f.getAll('equipment');save();render();toast('Profil gespeichert. Bestehende Pläne bei Bedarf neu erstellen.');};const rf=$('#race-form');if(rf)rf.onsubmit=ev=>{ev.preventDefault();const f=new FormData(rf),name=f.get('name').trim();if(!name)return;state.profile.competitions.push({id:crypto.randomUUID(),name,date:f.get('date'),sport:f.get('sport')});save();render();toast('Wettkampf gespeichert. Bitte die betroffene Woche neu planen.');};const file=$('#import-file');if(file)file.onchange=async()=>{try{const f=file.files[0];if(!f)return;if(f.size>2000000)throw Error();const data=JSON.parse(await f.text());if(!validBackup(data))throw Error();if(!confirm('Die Sicherung ersetzt die Trainingsdaten in diesem Browser. Fortfahren?'))return;state=data;save();render();toast('Deine Sicherung wurde geladen.');}catch{toast('Diese Datei ist keine gültige Athlet-Sicherung.');}};}
function validBackup(d){return d&&typeof d==='object'&&d.profile&&Array.isArray(d.profile.sports)&&d.profile.sports.length>0&&d.profile.sports.every(s=>typeof s==='string'&&E.sports[s])&&Array.isArray(d.profile.equipment)&&d.profile.equipment.every(s=>equipment.includes(s))&&[1,2,3,4,5,6].includes(Number(d.profile.count))&&[15,20,30,45,60,90].includes(Number(d.profile.minutes))&&Array.isArray(d.profile.goals)&&d.profile.goals.every(g=>g&&typeof g.id==='string'&&typeof g.title==='string'&&typeof g.focus==='string'&&(!g.date||/^\d{4}-\d{2}-\d{2}$/.test(g.date)))&&Array.isArray(d.profile.competitions)&&d.profile.competitions.every(c=>c&&typeof c.id==='string'&&typeof c.name==='string'&&typeof c.sport==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(c.date))&&Array.isArray(d.completed)&&d.completed.every(x=>typeof x==='string')&&d.plans&&typeof d.plans==='object'&&Object.entries(d.plans).every(([k,list])=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&Array.isArray(list)&&list.length<=6&&list.every(s=>s&&typeof s.id==='string'&&typeof s.focus==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&Number.isFinite(s.minutes)&&s.minutes>0&&s.minutes<=90&&Number.isInteger(s.day)&&s.day>=0&&s.day<7&&Array.isArray(s.sports)&&s.sports.every(x=>typeof x==='string')&&Array.isArray(s.blocks)&&s.blocks.length>0&&s.blocks.length<=30&&s.blocks.every(b=>b&&typeof b.name==='string'&&typeof b.instruction==='string'&&typeof b.kind==='string'&&Number.isInteger(b.seconds)&&b.seconds>0&&Number.isFinite(b.reps))));}
$('#plan-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),sports=f.getAll('sports');if(!sports.length){$('#form-error').textContent='Wähle mindestens eine Sportart.';return;}const week=f.get('week');if(state.plans[week]?.some(done)&&!confirm('Diese Woche enthält erledigte Einheiten. Den Plan neu erstellen und den Wochenfortschritt zurücksetzen?'))return;state.profile={...state.profile,sports,equipment:f.getAll('equipment'),count:Number(f.get('count')),minutes:Number(f.get('minutes'))};state.plans[week]=E.generate(state.profile,week);state.completed=state.completed.filter(id=>!id.startsWith(week));state.sunday=E.weekKey();selectedWeek=week;save();$('#editor').close();render();toast('Dein neuer Wochenplan ist bereit.');};
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.classList.contains('close-dialog')){b.closest('dialog').close();return;}if(b.dataset.detail){openDetail(b.dataset.detail);return;}if(b.dataset.start){startWorkout(b.dataset.start);return;}if(b.dataset.complete){toggleComplete(b.dataset.complete);return;}if(b.dataset.shift){weekShift(Number(b.dataset.shift));return;}if(b.dataset.goalToggle){const g=state.profile.goals.find(g=>g.id===b.dataset.goalToggle);if(g)g.done=!g.done;save();render();return;}if(b.dataset.goalDelete){state.profile.goals=state.profile.goals.filter(g=>g.id!==b.dataset.goalDelete);save();render();return;}if(b.dataset.raceDelete){state.profile.competitions=state.profile.competitions.filter(c=>c.id!==b.dataset.raceDelete);save();render();return;}switch(b.dataset.action){case'edit':openEditor();break;case'next-week':openEditor(true);break;case'current-week':selectedWeek=E.weekKey();render();break;case'play':togglePlay();break;case'previous':advance(-1);break;case'next':advance(1);break;case'exit-workout':pauseWorkout();if(confirm('Training verlassen? Diese Einheit bleibt als offen markiert.')){active=null;$('#workout').close();}break;case'rep':if(active){active.rep=(active.rep+1)%9;$('#rep-btn').textContent=active.rep+' / 8 ＋';if(active.rep)speak(String(active.rep));}break;case'export':download('athlet-sicherung.json','application/json',JSON.stringify(state,null,2));toast('Sicherung heruntergeladen.');break;case'import':$('#import-file').click();break;case'install':showInstall();break;case'reminder':reminder();break;}});
document.addEventListener('change',ev=>{if(ev.target.id==='voice'&&active){active.voice=ev.target.checked;if(active.voice)announce();else if('speechSynthesis'in window)speechSynthesis.cancel();}});
$('#workout').addEventListener('cancel',ev=>{if(active){ev.preventDefault();pauseWorkout();if(confirm('Training verlassen? Diese Einheit bleibt als offen markiert.')){active=null;$('#workout').close();}}});
$('#workout').addEventListener('close',()=>{stopTimer();active=null;if('speechSynthesis'in window)speechSynthesis.cancel();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&active?.running)pauseWorkout();});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installPrompt=ev;});
async function showInstall(){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else $('#install-dialog').showModal();}
$('#install-btn').onclick=showInstall;$('#reminder-btn').onclick=reminder;
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
render();

// Firebase session identity chooses a separate device-local training profile.
// Tokens and passwords are never copied into training backups or app storage.
window.addEventListener('athlet-auth-change', event => {
  const uid = event.detail.user?.uid;
  const nextKey = uid ? 'athlet-v1:account:' + uid : 'athlet-v1';
  if (nextKey === currentStorageKey) return;
  save();
  if (active) {pauseWorkout();active=null;}
  for (const id of ['workout','detail','editor']) if ($('#'+id).open) $('#'+id).close();
  currentStorageKey = nextKey;
  state = {profile:structuredClone(defaultProfile),plans:{},completed:[],sunday:null};
  try {const saved=JSON.parse(localStorage.getItem(currentStorageKey));if(validBackup(saved))state=saved;}catch{}
  selectedWeek=E.weekKey();
  if (!state.plans[selectedWeek])state.plans[selectedWeek]=E.generate(state.profile,selectedWeek);
  save();render();
});
